import React from 'react';
// Import Link from react-router-dom for client-side navigation
import { Link } from 'react-router-dom';

const styles = {
  header: {
    backgroundColor: '#004d40', // A deep, professional green
    color: 'white',
    padding: '24px',
    borderBottom: '4px solid #00796b',
  },
  container: {
    maxWidth: '1200px',
    margin: '0 auto',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  titleContainer: {
    // This container groups the title and subtitle
  },
  title: {
    fontSize: '2.5rem',
    fontWeight: 'bold',
    margin: 0,
    color: 'white', // Ensure title color is white
    textDecoration: 'none', // Remove underline if it's a link
  },
  subtitle: {
    fontSize: '1.25rem',
    marginTop: '4px',
    fontStyle: 'italic',
  },
  nav: {
    // No margin needed now as flexbox handles alignment
  },
  navLink: {
    color: 'white',
    textDecoration: 'none',
    marginLeft: '24px', // Use marginLeft for spacing between links
    fontSize: '1.1rem',
  },
};

const Header = () => {
  return (
    <header style={styles.header}>
      <div style={styles.container}>
        <div style={styles.titleContainer}>
          {/* Use Link component for the main title to navigate home */}
          <Link to="/" style={styles.title}>Karpagam Clinic</Link>
          <p style={styles.subtitle}></p>
        </div>
        <nav style={styles.nav}>
          {/* Use Link for SPA navigation */}
          <Link to="/" style={styles.navLink}>Home</Link>
          <Link to="/about" style={styles.navLink}>About Us</Link>
          {/* The "Contact Us" link now navigates to the form page */}
          <Link to="/contact" style={styles.navLink}>Contact Us</Link>
        </nav>
      </div>
    </header>
  );
};

export default Header;
